/** A interface do próprio recurso: nunca entra na captura nem no contexto. */
export const UI_ATTR = 'data-bug-ui';
const WINDOW_MS = 60_000;
let errors = [];
let installed = false;
function keep(message) {
  const now = Date.now();
  errors = errors.filter(e => now - e.time < WINDOW_MS).slice(-29);
  errors.push({
    time: now,
    message: message.slice(0, 500)
  });
}
function show(value) {
  if (value instanceof Error) return `${value.name}: ${value.message}`;
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}

/** Passa a guardar os erros do console e as exceções do último minuto. */
export function installConsoleCapture() {
  if (installed) return;
  installed = true;
  const original = console.error;
  console.error = (...args) => {
    try {
      keep(args.map(show).join(' '));
    } catch {
      // Nunca quebra a página.
    }
    original.apply(console, args);
  };
  window.addEventListener('error', e => keep(`${e.message}${e.filename ? ` (${e.filename.split('/').pop()}:${e.lineno})` : ''}`));
  window.addEventListener('unhandledrejection', e => keep(`Unhandled rejection: ${show(e.reason)}`));
}
function recentConsoleErrors() {
  const now = Date.now();
  return errors.filter(e => now - e.time < WINDOW_MS).map(e => ({
    at: new Date(e.time).toISOString(),
    message: e.message
  }));
}
const cssEscape = s => typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(s) : s.replace(/[^\w-]/g, '\\$&');

/** O nome do componente mais próximo, pelos `data-*` dos ancestrais. */
function componentName(el) {
  for (let node = el; node; node = node.parentElement) {
    for (const attr of ['data-component', 'data-screen', 'data-testid', 'data-id']) {
      const value = node.getAttribute(attr);
      if (value) return `${attr.slice(5)}:${value}`;
    }
  }
  return '';
}
function domPath(el) {
  const parts = [];
  for (let node = el; node && node !== document.body && parts.length < 6; node = node.parentElement) {
    const cls = (typeof node.className === 'string' ? node.className : '').split(/\s+/).filter(Boolean).slice(0, 2).map(c => `.${cssEscape(c)}`).join('');
    parts.unshift(`${node.tagName.toLowerCase()}${node.id ? `#${cssEscape(node.id)}` : ''}${cls}`);
  }
  return parts.join(' > ');
}

/** Os elementos sob o centro e os quatro quartos da área, do mais específico. */
function describeElements(rect) {
  const points = [[0.5, 0.5], [0.2, 0.2], [0.8, 0.2], [0.2, 0.8], [0.8, 0.8]].map(([fx, fy]) => [rect.x + rect.w * fx, rect.y + rect.h * fy]);
  const seen = new Set();
  const out = [];
  for (const [x, y] of points) {
    const stack = typeof document.elementsFromPoint === 'function' ? document.elementsFromPoint(x, y) : [];
    for (const el of stack) {
      if (el === document.documentElement || el === document.body || el.closest(`[${UI_ATTR}]`) || seen.has(el)) continue;
      seen.add(el);

      // Campos de senha não dão texto.
      const secret = !!el.closest('input[type="password"], [data-bug-mask]');
      if (out.length < 8) {
        out.push({
          path: domPath(el),
          component: componentName(el),
          text: secret ? '' : (el.textContent ?? '').replace(/\s+/g, ' ').trim().slice(0, 120)
        });
      }
      break;
    }
  }
  return out;
}
const REDACT = ['token', 'access_token', 'id_token', 'key', 'apikey', 'api_key', 'password', 'passwd', 'secret', 'auth', 'code', 'session', 'sid', 'jwt', 'signature', 'sig'];

/** A URL sem os parâmetros que costumam carregar segredos. */
export function redactUrl(href) {
  try {
    const url = new URL(href);
    for (const key of Array.from(url.searchParams.keys())) {
      if (REDACT.includes(key.toLowerCase())) url.searchParams.set(key, '[redacted]');
    }
    url.searchParams.delete('bugs');
    return url.toString();
  } catch {
    return href.slice(0, 1000);
  }
}
export function buildContext(region, includeConsole, route) {
  const root = document.documentElement;
  return {
    url: redactUrl(window.location.href),
    title: document.title.slice(0, 200),
    viewport: {
      w: window.innerWidth,
      h: window.innerHeight,
      dpr: window.devicePixelRatio || 1
    },
    region,
    userAgent: navigator.userAgent,
    language: navigator.language,
    route,
    theme: root.getAttribute('data-theme') || (root.classList.contains('dark') ? 'dark' : ''),
    elements: region ? describeElements(region) : [],
    consoleErrors: includeConsole ? recentConsoleErrors() : []
  };
}
flarum.reg.add('ramon-canela', 'forum/features/bugreports/context', { UI_ATTR: UI_ATTR,installConsoleCapture: installConsoleCapture,redactUrl: redactUrl,buildContext: buildContext, });